-- Ejemplo editable para probar alcance, área, atracción y derribo.
insert into public.forja_maestra(tipo,nombre,tipo_creacion,descripcion,configuracion_dados,stats,estado,es_grupo,creador_id)
select 'habilidades_generales','Azul','habilidad','Bola de energía azul: alcance 6 casillas, radio 2; causa 2d6 de daño y atrae hasta 2 casillas. Salvación CD 12: al fallar queda derribado; al superar recibe mitad del daño y sigue siendo atraído. Coste: 2 PH y una acción.','[{"id":"azul_atraccion","nombre":"Azul","descripcion":"Lanza una bola de energía azul. Daña y atrae a los enemigos del área hacia su centro; si fallan su salvación, quedan derribados.","efecto":"dano","cantidad":2,"caras":6,"modificador":0,"tipo_dano":"energía azul","elemento":"ninguno","naturaleza":"magica","estado":"","duracion":0,"coste_ph":2,"coste_fatiga":0,"salvacion":{"cd":12,"atributo":"salvacion","exito":"mitad"},"tablero":{"alcance":6,"forma":"circulo","tamano":2,"afecta":"enemigos","color":"azul","desplazamiento":{"tipo":"atraer","casillas":2,"cuando":"siempre"},"derribo":"fallo_salvacion"}}]'::jsonb,'{"enfriamiento":0}'::jsonb,'aprobado',false,(select id from public.perfiles where upper(rol)='KUROI' limit 1)
where not exists(select 1 from public.forja_maestra where nombre='Azul' and tipo_creacion='habilidad');
